# region: gather
def gather(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: intake
def intake(xs, factor=10):
    return [v * factor for v in xs]

# region: fold
def fold(xs, limit=20):
    return [v if v <= limit else limit for v in xs]

# region: shape
def shape(xs):
    return {'n': len(xs), 'total': max(xs)}

# region: digest
def digest(summary, bar=4):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return digest(shape(fold(intake(gather(raw)))))

